"""Go2-W in a world generated by navmap_gis_tool (Gazebo Harmonic).

  ros2 launch go2w_gazebo go2w_gis.launch.py world_package:=<generated package>

The legs are fixed in the standing pose and the wheels are a skid steer on /cmd_vel:
the robot drives like the real one in sport mode, it does not walk.
Topics are those of the real robot: /odom, /tf (odom -> base_footprint -> base_link),
/joint_states, /utlidar/cloud, /scan, /imu, plus /gps/fix and /clock.
"""

import glob
import math
import os
import xml.etree.ElementTree as ET

from ament_index_python.packages import get_package_share_directory
from launch import LaunchDescription
from launch.actions import (AppendEnvironmentVariable, DeclareLaunchArgument,
                            IncludeLaunchDescription, OpaqueFunction)
from launch.conditions import IfCondition
from launch.launch_description_sources import PythonLaunchDescriptionSource
from launch.substitutions import LaunchConfiguration
from launch_ros.actions import Node
import xacro

# Standing pose, same as sim_go2w (go2w_driver)
STAND_THIGH = 0.67
STAND_CALF = -1.3
# base_link height over the ground in that pose: thigh * cos(t) + calf * cos(t + c) + wheel
STAND_HEIGHT = 0.213 * math.cos(STAND_THIGH) + 0.2264 * math.cos(STAND_THIGH + STAND_CALF) + 0.086

WHEEL_RADIUS = 0.086
WHEEL_WIDTH = 0.052
WHEEL_OFFSET_Y = 0.048  # wheel center from the foot joint, from the wheel meshes


def sim_urdf(gazebo_xml):
    """go2w.urdf.xacro with fixed standing legs, cylinder wheels and the Gazebo additions."""
    xacro_file = os.path.join(
        get_package_share_directory('go2w_description'), 'urdf', 'go2w.urdf.xacro')
    robot = ET.fromstring(xacro.process_file(xacro_file).toxml())

    for joint in robot.findall('joint'):
        name = joint.get('name')
        if name.endswith(('_hip_joint', '_thigh_joint', '_calf_joint')):
            angle = 0.0
            if name.endswith('_thigh_joint'):
                angle = STAND_THIGH
            elif name.endswith('_calf_joint'):
                angle = STAND_CALF
            origin = joint.find('origin')
            # thigh and calf turn about y with no origin rotation: fixing them at an angle
            # is a pitch in the origin
            if any(float(v) != 0.0 for v in origin.get('rpy', '0 0 0').split()):
                raise RuntimeError(f'{name}: origin rpy not supported')
            origin.set('rpy', f'0 {angle} 0')
            joint.set('type', 'fixed')
            for tag in ('axis', 'limit', 'dynamics'):
                for child in joint.findall(tag):
                    joint.remove(child)

    # Wheel meshes as collision roll badly: a cylinder of the same size instead
    for link in robot.findall('link'):
        name = link.get('name')
        if not name.endswith('_foot') or name[:2] not in ('FL', 'FR', 'RL', 'RR'):
            continue
        y = WHEEL_OFFSET_Y if name[1] == 'L' else -WHEEL_OFFSET_Y
        for collision in link.findall('collision'):
            link.remove(collision)
        collision = ET.SubElement(link, 'collision')
        ET.SubElement(collision, 'origin', xyz=f'0 {y} 0', rpy=f'{math.pi / 2} 0 0')
        geometry = ET.SubElement(collision, 'geometry')
        ET.SubElement(geometry, 'cylinder', radius=str(WHEEL_RADIUS), length=str(WHEEL_WIDTH))
        gz = ET.SubElement(robot, 'gazebo', reference=name)
        ET.SubElement(gz, 'mu1').text = '1.0'
        ET.SubElement(gz, 'mu2').text = '1.0'

    for element in ET.parse(gazebo_xml).getroot():
        robot.append(element)
    return ET.tostring(robot, encoding='unicode')


def terrain_height(world_share, x, y):
    """Height of the generated terrain at (x, y), from the nearest point of maps/*.pcd."""
    clouds = glob.glob(os.path.join(world_share, 'maps', '*.pcd'))
    if not clouds:
        return 0.0
    best, height = float('inf'), 0.0
    with open(clouds[0]) as f:
        for line in f:
            if line.startswith('DATA'):
                if 'ascii' not in line:
                    return 0.0
                break
        for line in f:
            px, py, pz = (float(v) for v in line.split()[:3])
            d = (px - x) ** 2 + (py - y) ** 2
            if d < best:
                best, height = d, pz
    return height


def launch_setup(context):
    pkg = get_package_share_directory('go2w_gazebo')
    world_package = LaunchConfiguration('world_package').perform(context)
    world_share = get_package_share_directory(world_package)
    worlds = glob.glob(os.path.join(world_share, 'worlds', '*.world'))
    if not worlds:
        raise RuntimeError(f'no worlds/*.world in {world_share}')

    x = float(LaunchConfiguration('x').perform(context))
    y = float(LaunchConfiguration('y').perform(context))
    yaw = LaunchConfiguration('yaw').perform(context)
    z = terrain_height(world_share, x, y) + STAND_HEIGHT + 0.05

    robot_description = sim_urdf(os.path.join(pkg, 'urdf', 'gazebo.xml'))
    sim_time = {'use_sim_time': True}
    gui = LaunchConfiguration('gui').perform(context) == 'true'

    return [
        # package://go2w_description/... meshes are looked up in the parent of its share dir
        AppendEnvironmentVariable(
            'GZ_SIM_RESOURCE_PATH',
            os.path.dirname(get_package_share_directory('go2w_description'))),
        AppendEnvironmentVariable('GZ_SIM_RESOURCE_PATH', os.path.join(world_share, 'models')),

        IncludeLaunchDescription(
            PythonLaunchDescriptionSource(os.path.join(
                get_package_share_directory('ros_gz_sim'), 'launch', 'gz_sim.launch.py')),
            launch_arguments={
                'gz_args': ('-r ' if gui else '-r -s ') + worlds[0],
                'on_exit_shutdown': 'true',
            }.items()),

        Node(
            package='ros_gz_sim',
            executable='create',
            arguments=['-name', 'go2w', '-string', robot_description,
                       '-x', str(x), '-y', str(y), '-z', str(z), '-Y', yaw],
            output='screen'),

        Node(
            package='ros_gz_bridge',
            executable='parameter_bridge',
            parameters=[{'config_file': os.path.join(pkg, 'config', 'bridge.yaml')}, sim_time],
            output='screen'),

        Node(
            package='robot_state_publisher',
            executable='robot_state_publisher',
            parameters=[{'robot_description': robot_description}, sim_time]),

        # OdometryPublisher gives odom -> base_footprint at the body: base_link on top of it,
        # as go2w_driver does with base_height_offset 0
        Node(
            package='tf2_ros',
            executable='static_transform_publisher',
            arguments=['--frame-id', 'base_footprint', '--child-frame-id', 'base_link'],
            parameters=[sim_time]),

        Node(
            package='pointcloud_to_laserscan',
            executable='pointcloud_to_laserscan_node',
            name='pointcloud_to_laserscan',
            parameters=[os.path.join(get_package_share_directory('go2w_bringup'), 'config',
                                     'pointcloud_to_laserscan.yaml'), sim_time],
            remappings=[('cloud_in', '/utlidar/cloud'), ('scan', '/scan')]),
    ]


def generate_launch_description():
    return LaunchDescription([
        DeclareLaunchArgument('world_package',
                              description='Package generated by navmap_gis_tool --gazebo'),
        DeclareLaunchArgument('x', default_value='0.0'),
        DeclareLaunchArgument('y', default_value='0.0'),
        DeclareLaunchArgument('yaw', default_value='0.0'),
        DeclareLaunchArgument('gui', default_value='true'),
        DeclareLaunchArgument('rviz', default_value='false'),
        OpaqueFunction(function=launch_setup),
        Node(
            package='rviz2',
            executable='rviz2',
            # Fixed Frame map: EasyNav goals must be in map (GoalManager does not transform them)
            arguments=['-d', os.path.join(get_package_share_directory('go2w_gazebo'),
                                          'rviz', 'go2w_sim.rviz')],
            parameters=[{'use_sim_time': True}],
            condition=IfCondition(LaunchConfiguration('rviz'))),
    ])
